import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"未濟","description":"高島易斷 - 未濟","frontmatter":{"title":"未濟","description":"高島易斷 - 未濟"},"headers":[],"relativePath":"classics/takashima/064.md","filePath":"classics/takashima/064.md"}'),i={name:"classics/takashima/064.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="未濟" tabindex="-1">未濟 <a class="header-anchor" href="#未濟" aria-label="Permalink to “未濟”">​</a></h1><h2 id="未濟-1" tabindex="-1">未濟 <a class="header-anchor" href="#未濟-1" aria-label="Permalink to “未濟”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>未濟：亨，小狐汔濟，濡其尾，無攸利。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>不曰不濟，而曰“未濟”，非安處不濟也，未耳。蓋《未濟》而自有可濟，亦未亨而自有可亨，故曰“未濟亨”。《坎》為小狐，“汔”，幾也。濟必登岸，始為《既濟》，一步不至，猶未也，“汔濟”安得為濟哉！小狐力弱，中流失濟，尾重不掉，難免濡矣，復有何利？故曰“小狐汔濟，濡其尾，無攸利”也。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>火在水上，未濟。君子以慎辨物居方。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>火熱水寒，物之各異其性也；《離》南《坎》北，方之各殊其位也。火在水上，是炎上潤下，並失其位，兩不相濟也，故曰《未濟》。君子觀其象，而辨之居之，辨其物，使物得其宜，而不相混，居其方，使方從其位，而不相越。皆以審慎而出之，斯知之無不明，處之無不當，而其未濟者乃可進於濟矣，故曰“君子以慎辨物居方”。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：運途顛倒，諸事須慎。</p><p>○　問營商：貨物失當，地位不合，所當謹慎處置，方可獲利。</p><p>○　問功名：未也。</p><p>○　問戰徵：營壘器具，各失所宜，不相為用，急宜慎重審察，斯可免敗。</p><p>○　問家宅：方向倒置，須當改易。</p><p>○　問婚姻：門戶不合。</p><p>○　問疾病：上下焦血絡不通，宜升不升，宜降不降，藥方最宜審慎。</p><p>○　問失物：辨明方位，可以尋得。</p><p>○　問六甲：上月生女，下月生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初居《未濟》之始，《彖》所云“小狐汔濟，濡其尾”，初爻當之。《未濟》之初，與《既濟》之上，首尾相接，《既濟》之上，以濡首而厲，初踵其後，見上之濡首，反而自懲，未濟者亦可免於濡矣，乃前首後尾，同遭其濡，頑不知戒，故曰“吝”也。《象傳》以“亦不知極”釋之，謂前覆其轍，後又不知而蹈之，故曰亦術知其極也。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運：不審前後，不顧進退，魯莽從事，是昏而無知者也。</p><p>○　問營商：前既失敗，後又不戒，覆轍相仍，其將何以了事乎？</p><p>○　問功名：龍頭既失，驥尾亦必難附。</p><p>○　問婚姻：流離首尾，團聚難矣。</p><p>○　問家宅：此宅前門後戶，方位不正。</p><p>○　問疾病：病在下身。</p><p>○　問六甲：生男。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某來，請佔製造物品生業如何，筮得《未濟》之《睽》。</p><p>斷曰：初居《未濟》之初，正在濟末將濟之時，《既濟》之終“濡其首”，《未濟》之始“濡其尾”，有首尾不相顧之象。今君佔製造生業，得此爻辭，知此業必是舊業，君接其後而重興也。君乃不知前車之覆，貿然而蹈其後，以致製品所出，一時不能銷售。以此質金，反致失利，得失不償，進退兩難，幾同“小狐汔濟”，而“濡其尾”也，未免吝矣。至二爻曰“曳其輪，貞吉”，在明年當以車運出外，可以販賣獲利也，君可無憂焉。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>二居《坎》之中，《坎》為輪，故曰“輪”。輪者，濟之具也。《既濟》初爻曰曳輪而濡尾，有濟之具而濡者也；此曰曳輪，而不曰濡尾，有濟之具而不濡者也，視《既濟》之初為優矣，故曰“貞吉”。《坎》又為矯輮，按《周禮·考工記》，“行澤者反輮，行山者仄輮”，取其便於曳也。御輪濟水，中道而行，其濟以正，是為中行以正，吉何如之！《象傳》所釋，最為明著。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：運如輕車渡水，中道以濟，無往不利。</p><p>○　問營商：有滿載而歸之象。</p><p>○　問功名：二與五應，五為君，二為臣，二五皆吉，是君臣相濟也。有後車以載之象。</p><p>○　問戰徵：有曳柴偽遁之謀。</p><p>○　問婚姻：有桓少君鹿車共挽之風，必得賢婦，吉。</p><p>○　問家宅：有輪奐並美之象。</p><p>○　問疾病：必是胸腹作鳴，轆轆如車聲，宜開通三焦，使氣機舒展，自愈。</p><p>○　問六甲：生男。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>明治八年九月，朝鮮國炮擊我雲揚艦，物論洶洶，朝廷將興問罪之師。時陸軍大佐某氏來請一佔，筮得《未濟》之《晉》。</p><p>斷曰：水火不交，不相為用，謂之《未濟》。然未濟非不濟也，時未至則不濟，時至則濟，故曰“未濟亨”。為卦皆取水火，《既濟》水在火上，初爻曰曳輪，是為陸道之輪車也；《未濟》火在水上，二爻曰曳輪，是為海道之輪船也。今雲揚艦被朝鮮炮擊，爻曰“曳其輪，貞吉”，想雖被擊，尚可曳輪而歸，故不失其吉也。《象傳》曰“中以行正”，言必得中和之道，以行其正，今年必不致構怨興兵也。至三爻曰“徵兇，利涉大川”，恐明年有事於朝鮮。曰“徵兇”者，恐陸軍不利；曰“利涉大川”者，知海軍必大勝也。九四曰“貞吉，悔亡，震用伐鬼方，三年有賞於大國”，自二至四為後年，必可解決朝鮮之事矣。且二爻變而為《晉》，晉者，進也，《晉》五曰“失得勿恤，往吉，無不利”；上曰“晉其角，維用伐邑，厲吉，無咎”，是皆征伐有功之佔也。佔象如是，知以後必獲大功。但《未濟》以外卦為《既濟》，內卦為將濟，佔在二爻，故今年未能成事，必待外卦，乃得全濟也。後朝鮮事局平和，征討不興，於是某氏來曰：前日之佔，事未甚驗，餘曰：《易》佔無不靈應，但所應有不在一時也。現雖歸和平，其“中以行正”一語，恰好符合，此後佔象，君須緩以待之，無不應也。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>三爻以陰居陽，當內外卦之交，首尾俱不著岸，故爻曰“未濟”。專以卦名歸之，謂《未濟》之所以未濟者，在此爻也。三為《坎》之，地當重要，進一步則出險，誤一步即履危，魯莽前進，一經失足，功敗垂成，故曰“徵兇”。然《未濟》有可濟之道，有險有出險之時，自古定大難，建大功者，罔非從“徵兇”之時而興起也。所謂“徵兇”者，第戒其不可妄動，非欲其退縮不前。三之地，正當利涉之地，三之時，正當利涉之時，此而不濟，則終不濟矣，此而得濟，則汔濟者乃得濟矣。《象傳》曰“位不當也”，《未濟》六爻，位皆不當，三為《坎》之終，故《傳》專以不當釋之。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：宜鎮靜待時，躁動則兇。</p><p>○　問戰徵：宜會集海軍，水陸並進，則兇者吉矣。</p><p>○　問營商：以舟運為利。</p><p>○　問功名：有涉川作楫之材。</p><p>○　問婚姻：《詩》雲“造舟為梁，親迎於渭”，迎娶則吉，往贅則兇。</p><p>○　問疾病：《艮》為狐，病由狐祟所致，宜涉川以避。</p><p>○　問六甲：生男。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>三十年，佔眾議院氣運，筮得《未濟》之《鼎》。</p><p>斷曰：此卦火上水下，水火不相為用，故曰“未濟”。三爻居上下內外之交，出《坎》入《離》，正當《未濟》之時，是以爻辭直曰“未濟”。曰“徵兇”者，指初之濡尾也；曰“利涉”者，指二之曳輪也，為利為兇，任人自為之耳。《傳》則釋曰“位不當”，於此即可見眾議院之氣運矣。蓋在政府欲效歐美之文明，以圖富強；在眾議員，欲學歐美之自由，以圖權利，猶之火上水下，兩不相濟也。且現時所選議員，多由賄賂而來，是明明位之不當也，由此以往，安得不兇？故曰“徵兇”。然於議院之設，苟當其位，而“中以行正”，未始無利，故曰“利涉大川”。但此爻處《坎》之終，猶未出險，今年眾議院，正當未濟之地，難期盛旺。四爻曰“貞吉，悔亡，震用伐鬼方，三年有賞於大國”，知明年眾議院，必得其人，能贊襄國家大事，勞邀厚賜，此盛象也。五曰“君子之光”，五為君，定當入觀天顏，武功文德，並煥輝光矣。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>《未濟》濟在四，《既濟》濟在三，《未濟》之四，即《既濟》之三，故爻辭皆曰“伐鬼方”。三居《離》之始，《離》為戈兵，故“用伐”。《坎》為鬼，故取象於“鬼方”。“震”者，威怒之象，所謂一怒而安天下之民也。《未濟》則有悔，濟則悔亡。故曰“貞吉，悔亡”。“三年”者，言其久也，即《既濟》三爻所云“三年克之”也。“有賞”者，為獻俘授馘飲，至大賞是也。“大國”謂殷，爻雖不明言高宗，要不出《既濟》三爻之義也。《象傳》曰“志行”，謂班師奏凱，威震遐方，主三軍者，得行其志矣。《既濟》三爻《傳》曰“憊也”，為勞師遠征而言；此《傳》曰“志行”，為振旅告捷而言。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：有此大運，“貞吉，悔亡”，名利俱全。</p><p>○　問戰徵：率軍遠征，奏凱而還，得以榮邀賜命。</p><p>○　問營商：行商遠出，財利豐盈。</p><p>○　問功名：聲名遠震，得承天寵。</p><p>○　問婚姻：三年可成。</p><p>○　問家宅：貞吉。</p><p>○　問疾病：“鬼方”二字不祥，三年後恐難保。</p><p>○　問六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>友人某來請佔氣運，筮得《未濟》之《蒙》。</p><p>斷曰：此卦下三爻為《未濟》之時，上三爻為《既濟》之時，今佔得四爻，知年來困苦之事，漸》次可奏成功，謂之“貞吉，悔亡”。“震用伐鬼方，三年有賞於大國”者，知君於此三年中，得以威名遠揚，賞賜榮膺，為生平業成志滿之時也。</p><p>明治二十七年冬至，謹佔二十八年聖運，筮得《未濟》之《蒙》。</p><p>斷曰：四爻當內外之交，出《坎》入《離》，為脫險難而進文明，是由《未濟》而抵《既濟》也。今佔得四爻，爻曰“震用伐鬼方”，是為徵清得勝也；“三年”者，謂戰役之久；“有賞於大國”者，謂奏凱行賞也。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>五為《未濟》一卦之主，居《離》之中，與四相比，與二相應。二以居中行正，四以征伐有功，當此文德昭明，武功顯著；臣下之勳業，要即為天子之威光也，故曰“君子之光”。柔得中，故“貞吉，無悔”。《離》為明，為光，德莫盛於明，業莫大於光，六五之君，和順積中，英華髮外，其光皆出於君子之身，天下莫不仰文明之化，故曰“有孚，吉”。《象傳》以“暉吉”釋之，謂其篤實輝光，自然昭著，吉何如也！</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：運當全盛，百事皆吉。</p><p>○　問戰徵：《師》卦曰“師貞，丈人吉”，可並佔之。</p><p>○　問營商：其營業必關係政府公幹，或為軍餉，或為軍器，得沾朝廷之餘澤，故吉。</p><p>○　問功名：有入覲天顏之象。</p><p>○　問家宅：此宅大吉，當邀旌賜之勞。</p><p>○　問婚姻：“君子好逑”，必得。</p><p>○　問六甲：生女，主貴。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>某縉紳來，請佔官階升遷，筮得《未濟》之《訟》。</p><p>斷曰：五爻居《離》之中，《離》為日，為光，五當君位，日有君象，故曰“君子之光”。日光照臨，下土遍被，故曰“有孚”。五與二應，二為臣，是先得“君子之光”者也。今足下佔祿位升，得《未濟》五爻，五為尊位，二爻屬貴下，二爻曰“曳其輪，貞吉”，輪為日輪，曳輪者，有如羲和御日，是為天子之近臣，沐浴聖化，瞻仰龍光，君明臣良，可為貴下賀焉。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上爻當《未濟》之終，反為《既濟》，坎險已脫，上下交孚，則飲食以燕樂之。《詩》“南有嘉魚，君子有酒，嘉賓式燕以樂”，《序》曰太平君子至誠。樂與賢者共之，有孚於酒食之義也，故“無咎”。然酒以成禮，不及於亂，立監立史，所以示其節也，“濡其首”，則醉而不出，是謂伐德，亦何取於孚矣，故曰“有孚失是”。是始為有孚而飲酒者，繼反為飲酒而失孚也，《象傳》以“不知節”釋之。《易》之為書，患太過，更甚於防不及，欲不可縱，樂不可極，持盈保泰，無非節也。此特於《未濟》之終，借飲酒以為喻耳。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：《坎》難已平，眾心歡樂，能知撙節，可以永保無咎。</p><p>○　問戰徵：此為得勝班師，飲酒策勳之時也。</p><p>○　問營商：已得厚利而歸，從此量入為出，富可永保矣。</p><p>○　問功名：有得而復失之患。</p><p>○　問疾病：必是飲食不節所致。</p><p>○　問訟事：《序卦》曰“飲食必有訟”，知其訟必由於酗酒來也。</p><p>○　問六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>二十八年七月廿七日薄暮，餘與友閒敘於書樓，偶聞有叫新聞號外者，客曰：號外所報，不審何事，君試佔之。筮得《未濟》之《解》。</p><p>斷曰：號外所報，必因飲酒過度，醉溺水中之禍也。時女僕適齎號外來，展而閱之，為山陽鐵道，汽車顛覆中途，致傷旅客之報也。後數日，會該鐵道會社員，問及當時情況，曰：會風雨暴作，勸令止車，機關師某不肯，臨行且滿酌火酒，啟車而進，猝罹此禍，因此傷命雲。乃知爻辭，果不虛也。</p>',102)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
